+namespace ecliptic_movie {
+struct SnapshotRedirect {
+  Solver& solver;fs::path parked_path;int parked_index;std::ofstream parked_manifest;
+  SnapshotRedirect(Solver& s,const fs::path& target,int index):solver(s),parked_path(target),parked_index(s.snapshotidx) {
+    // Open/check before changing any parent host member, so construction failures
+    // leave the original stream/path/index intact.
+    std::ofstream incoming(target/"snapshots.csv",std::ios::app);
+    if(!incoming)throw std::runtime_error("Cannot open sparse diagnostic manifest");
+    parked_manifest.swap(s.manifest);s.manifest.swap(incoming);
+    s.out.swap(parked_path);s.snapshotidx=index;
+  }
+  ~SnapshotRedirect() noexcept {
+    solver.manifest.close();solver.manifest.swap(parked_manifest);
+    solver.out.swap(parked_path);solver.snapshotidx=parked_index;
+  }
+  SnapshotRedirect(const SnapshotRedirect&)=delete;
+  SnapshotRedirect& operator=(const SnapshotRedirect&)=delete;
+};
+
+struct DiagnosticVolumes {
+  std::vector<double> requests;size_t next=0;int index=0;bool initialized=false;
+  fs::path directory;std::ofstream requested_actual;
+  explicit DiagnosticVolumes(const Config& c) {
+    std::string text=c.s("diagnostic_volume_days");if(trim(text).empty())return;
+    std::replace(text.begin(),text.end(),',',' ');std::istringstream stream(text);double day;
+    while(stream>>day) {
+      if(!std::isfinite(day)||(!requests.empty()&&day<=requests.back()))throw std::runtime_error("diagnostic_volume_days must be finite and strictly increasing");
+      if(day>c.d("end_day",20)+1e-12)throw std::runtime_error("Diagnostic volume requested after run end");
+      requests.push_back(day);
+    }
+    if(!stream.eof()||requests.empty()||requests.size()>4)throw std::runtime_error("diagnostic_volume_days requires at most four numeric days");
+    size_t bytes=size_t(c.i("nr",64))*c.i("ntheta",8)*c.i("nphi",48)*8*sizeof(float)*requests.size();
+    if(bytes>400000000ULL)throw std::runtime_error("Sparse diagnostic volumes exceed conservative400MB disk budget");
+  }
+  void initialize(Solver& s) {
+    directory=s.out/"diagnostic_volumes";fs::create_directories(directory);
+    for(const std::string& name:{"r_au.npy","theta_rad.npy","phi_rad.npy"})
+      fs::copy_file(s.out/name,directory/name,fs::copy_options::overwrite_existing);
+    {std::ofstream manifest(directory/"snapshots.csv");manifest<<"day,file\n";if(!manifest)throw std::runtime_error("Cannot initialize sparse manifest");}
+    requested_actual.open(directory/"requested_vs_actual.csv");requested_actual<<"requested_day,actual_day,file\n";
+    std::ofstream config(directory/"run.cfg");for(const auto& item:s.c.a)config<<item.first<<'='<<item.second<<'\n';
+    std::ofstream parent(directory/"parent.json");
+    parent<<"{\"parent_output_directory\":\"..\",\"parent_probe_file\":\"../probe.csv\",\"parent_metadata_file\":\"../metadata.json\",\"parent_run_config_file\":\"../run.cfg\",\"configuration_snapshot\":\"run.cfg\",\"comet_probe_id\":0}\n";
+    std::ofstream meta(directory/"metadata.json");
+    meta<<std::setprecision(17)<<"{\"format\":\"frozen_solver_primitive_snapshot_v1\",\"origin_utc\":"<<json_string(s.c.s("origin_utc","2025-11-01T00:00:00Z"))
+        <<",\"day_units\":\"UTC days since origin_utc\",\"shape_order\":[\"radius\",\"theta\",\"phi\",\"field\"],\"shape\":["<<s.nr<<','<<s.nt<<','<<s.np<<",8],\"fields\":[\"n_cm3\",\"vr_kms\",\"vtheta_kms\",\"vphi_kms\",\"p_npa\",\"Br_nt\",\"Btheta_nt\",\"Bphi_nt\"],\"field_units\":[\"cm^-3\",\"km/s\",\"km/s\",\"km/s\",\"nPa\",\"nT\",\"nT\",\"nT\"],\"coordinate_frame\":\"fixed solver solar-equatorial spherical coordinates; theta increases southward\",\"axis_files\":[\"r_au.npy\",\"theta_rad.npy\",\"phi_rad.npy\"],\"axis_units\":[\"AU\",\"rad\",\"rad\"],\"requested_volume_days\":[";
+    for(size_t j=0;j<requests.size();++j)meta<<(j?",":"")<<requests[j];
+    meta<<"],\"sampling\":\"frozen Solver::snapshot of exact accepted conserved state at first regular snapshot day>=request; no time interpolation and no timestep clipping added\",\"parent_pointer_file\":\"parent.json\",\"requested_actual_file\":\"requested_vs_actual.csv\",\"gamma\":"<<s.gamma<<",\"physical_radial_bounds_au\":["<<s.rmin<<','<<s.rmax<<"],\"latitude_bound_rad\":"<<s.latmax<<"}\n";
+    if(!requested_actual||!config||!parent||!meta)throw std::runtime_error("Cannot initialize sparse diagnostic metadata");
+    initialized=true;
+  }
+  void snapshot(Solver& s,double day) {
+    if(next>=requests.size()||day<requests[next]-1e-10)return;
+    if(!initialized)initialize(s);
