+      std::ostringstream name;name<<"snapshot_"<<std::setfill('0')<<std::setw(5)<<index<<".npy";
+      {
+        SnapshotRedirect redirected(s,directory,index);
+        // The GPU state was already downloaded by gpu_snapshot. The frozen host
