+        s.snapshot(day);index=s.snapshotidx;
+      }
+      requested_actual<<std::setprecision(17)<<requests[next]<<','<<day<<','<<name.str()<<'\n';requested_actual.flush();
+      if(!requested_actual)throw std::runtime_error("Cannot append sparse requested/actual mapping");
+      ++next;
+    }
+  }
+};
